/// <summary>One operation of the API.</summary>
public sealed class Operation
{
    internal Operation(string id, string method, string path)
    {
        Id = id;
        Method = method;
        Path = path;
    }

    /// <summary>The operation id (<c>crm.records.create</c>).</summary>
    public string Id { get; }

    /// <summary>The HTTP method.</summary>
    public string Method { get; }

    /// <summary>The path; <c>{name}</c> is a path parameter.</summary>
    public string Path { get; }
}
